import {refineSurfaceMaterials100} from './visual-quality100.js?v=185';
import * as T from 'three';
// Keep the authored skinned palm/fingers and remove its rigid sleeve extension.
export function trimGlove177(root){root.traverse(o=>{if(!o.isSkinnedMesh||o.userData.trim177)return;const g=o.geometry.clone(),p=g.attributes.position,old=g.index,keep=[];for(let i=0;i<(old?.count||p.count);i+=3){const ids=[0,1,2].map(j=>old?old.getX(i+j):i+j);if(ids.every(k=>p.getY(k)>=-.105))keep.push(...ids);}g.setIndex(keep);g.computeBoundingBox();g.computeBoundingSphere();o.geometry=g;o.userData.trim177=true;});if(!root.getObjectByName('Union flexible de muñeca193')){const cuff=new T.Mesh(new T.SphereGeometry(.039,32,20),new T.MeshStandardMaterial({name:'Tejido flexible de muñeca193',color:'#344550',roughness:.92}));cuff.name='Union flexible de muñeca193';cuff.position.y=-.096;cuff.scale.set(1,.8,.9);root.add(cuff);}}
function sleeve(a,b,length){const pts=Array.from({length:25},(_,i)=>{const y=i/24,t=y*y*(3-2*y),radius=T.MathUtils.lerp(a,b,t)*(1+.045*Math.sin(y*Math.PI*2));return[y,radius];}),rings=pts.length,sides=40,pos=[],uv=[],idx=[];for(const[y,r]of pts)for(let j=0;j<=sides;j++){const t=j/sides*Math.PI*2;const fold=1+.012*Math.sin(y*28+t*3)+.008*Math.sin(y*52-t*2);pos.push(Math.cos(t)*r*fold,y*length,Math.sin(t)*r*.86*fold);uv.push(j/sides,y);}for(let i=0;i<rings-1;i++)for(let j=0;j<sides;j++){const k=i*(sides+1)+j;idx.push(k,k+sides+1,k+1,k+1,k+sides+1,k+sides+2);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return g;}
export class Arm177{
 constructor(parent,side=1){this.side=side;this.upperLength=.32;this.lowerLength=.28;this.root=new T.Group();this.root.name='Brazo articulado177';const mat=new T.MeshStandardMaterial({name:'Manga textil177',color:'#344550',roughness:.92});this.upper=new T.Mesh(sleeve(.060,.047,this.upperLength),mat);this.lower=new T.Mesh(sleeve(.047,.032,this.lowerLength),mat);this.elbow=new T.Mesh(new T.SphereGeometry(.053,20,12),mat);this.elbow.scale.z=.88;const cuffMat=new T.MeshStandardMaterial({name:'Puño tejido reforzado187',color:'#233943',roughness:.96});this.cuff=new T.Mesh(new T.CylinderGeometry(.033,.036,.042,40,4,true),cuffMat);this.cuff.position.y=this.lowerLength-.018;this.lower.add(this.cuff);const seamMat=new T.MeshStandardMaterial({name:'Costura de manga187',color:'#657984',roughness:.95});for(const mesh of[this.upper,this.lower]){const seam=new T.Mesh(new T.TorusGeometry(mesh===this.upper?.061:.045,.0012,5,40),seamMat);seam.rotation.x=Math.PI/2;seam.position.y=mesh===this.upper?.15:.13;mesh.add(seam);}this.elbow.geometry.dispose();this.elbow.geometry=new T.SphereGeometry(.046,32,20);this.root.add(this.upper,this.lower,this.elbow);refineSurfaceMaterials100(this.root);parent.add(this.root);this.root.visible=false;}
 pose(wrist,idealShoulder){const total=this.upperLength+this.lowerLength,direction=wrist.clone().sub(idealShoulder),distance=T.MathUtils.clamp(direction.length(),.10,total-.035);direction.normalize();const shoulder=idealShoulder.clone(),end=shoulder.clone().addScaledVector(direction,distance),a=(this.upperLength**2-this.lowerLength**2+distance**2)/(2*distance),height=Math.sqrt(Math.max(0,this.upperLength**2-a*a));let bend=new T.Vector3(this.side*.25,-1,.05);bend.addScaledVector(direction,-bend.dot(direction)).normalize();const elbow=shoulder.clone().addScaledVector(direction,a).addScaledVector(bend,height);for(const[mesh,from,to]of[[this.upper,shoulder,elbow],[this.lower,elbow,end]]){mesh.position.copy(from);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),to.clone().sub(from).normalize());}this.elbow.position.copy(elbow);this.shoulder=shoulder;this.wrist=end;this.joint=elbow;this.root.visible=true;}
 hide(){this.root.visible=false;}
}
